#include "taylor.hpp"
#include "inputs/q_null_feedback.hpp"
#include <iomanip>
#include <iostream>
#include <string>
#include <vector>
namespace hyp=z4c::hyperboloidal;
using Jet=hyp::Z4cJet<D>;using Point=hyp::LayerPoint<D>;using V=std::array<D,20>;
using Frame=std::array<std::array<long double,3>,3>;
const int ti[5]={0,0,0,1,1},tj[5]={0,1,2,1,2};
Frame Axes(int orientation){if(!orientation)return {{{1,0,0},{0,1,0},{0,0,1}}};return {{{.36L,-.48L,.8L},{.8L,.6L,0},{-.48L,.64L,.6L}}};}
std::array<D,3> Positions(const Frame&e){std::array<D,3>x{};for(int i=0;i<3;++i){x[i]=e[0][i];for(int j=0;j<3;++j)x[i]+=D(e[j][i])*D(Poly::Variable(j));}return x;}
Point Reference(const std::array<D,3>&x,long double a){return hyp::LayerReference<D>(D(1),D(a),{true,.05,.95}).At(x[0],x[1],x[2]);}
struct J{D v{},d[3]{},dd[3][3]{};};
J SeedJet(const Poly&f,const Frame&e){J z;z.v=D(Poly(0),f);for(int i=0;i<3;++i){Poly d;for(int k=0;k<3;++k)d+=e[k][i]*Derivative(f,k);z.d[i]=D(Poly(0),d);for(int j=0;j<3;++j){Poly dd;for(int k=0;k<3;++k)for(int l=0;l<3;++l)dd+=e[k][i]*e[l][j]*Derivative(Derivative(f,k),l);z.dd[i][j]=D(Poly(0),dd);}}return z;}
void Scalar(hyp::ScalarJet<D>&s,const J&z){s.value+=z.v;for(int i=0;i<3;++i){s.d[i]+=z.d[i];for(int j=0;j<3;++j)s.dd[i][j]+=z.dd[i][j];}}
void Vector(hyp::VectorJet<D>&s,int component,const J&z,long double scale){s.value[component]+=D(scale)*z.v;for(int i=0;i<3;++i){s.d[i][component]+=D(scale)*z.d[i];for(int j=0;j<3;++j)s.dd[i][j][component]+=D(scale)*z.dd[i][j];}}
void Tensor(Jet&u,int i,int j,const J&z,long double scale,bool A){if(A){u.a.k[i][j]+=D(scale)*z.v;for(int d=0;d<3;++d)u.a.dk[d][i][j]+=D(scale)*z.d[d];}else{u.metric.g[i][j]+=D(scale)*z.v;for(int d=0;d<3;++d){u.metric.dg[d][i][j]+=D(scale)*z.d[d];for(int e=0;e<3;++e)u.metric.ddg[d][e][i][j]+=D(scale)*z.dd[d][e];}}}
void Seed(Jet&u,int field,const J&z,const Frame&e){if(field==0)Scalar(u.alpha,z);if(field==1)Scalar(u.chi,z);if(field==2)Scalar(u.trace,z);if(field==3)Scalar(u.theta,z);
 if(field>=4&&field<7)for(int i=0;i<3;++i)Vector(u.beta,i,z,e[field-4][i]);
 if(field>=17)for(int i=0;i<3;++i)Vector(u.lambda,i,z,e[field-17][i]);
 if(field>=7&&field<17){const bool A=field>=12;const int k=field-(A?12:7),a=ti[k],b=tj[k];for(int i=0;i<3;++i)for(int j=0;j<3;++j){long double scale=e[a][i]*e[b][j];if(a!=b)scale+=e[b][i]*e[a][j];else scale-=e[2][i]*e[2][j];Tensor(u,i,j,z,scale,A);}}
}
hyp::OmegaJet<D> Omega(const Point&p,const Jet&u){hyp::OmegaJet<D>o{};o.omega=p.omega;for(int i=0;i<3;++i){o.gradient[i]=p.domega[i];for(int j=0;j<3;++j)o.hessian[i][j]=p.omega_hessian[i][j];}hyp::SetStationaryOmegaNormal(u.alpha.value,u.beta.value,u.alpha.d,u.beta.d,o);return o;}
V Fields(const hyp::Z4cRHS<D>&f,const hyp::GaugeRHS<D>&g,const Frame&e){V v{};v[0]=g.alpha;v[1]=f.chi;v[2]=f.trace;v[3]=f.theta;for(int k=0;k<3;++k)for(int i=0;i<3;++i){v[4+k]+=D(e[k][i])*g.beta[i];v[17+k]+=D(e[k][i])*f.lambda[i];}for(int k=0;k<5;++k)for(int i=0;i<3;++i)for(int j=0;j<3;++j){v[7+k]+=D(e[ti[k]][i]*e[tj[k]][j])*f.metric[i][j];v[12+k]+=D(e[ti[k]][i]*e[tj[k]][j])*f.a[i][j];}return v;}
struct RS{hyp::Z4cRHS<D> r{},s{};hyp::GaugeRHS<D>gr{},gs{};};
RS Parts(const Point&p,const Jet&u,long double sigma=3){const auto f=hyp::ConformalRHS(u,Omega(p,u),D(10)/u.alpha.value,D(0));hyp::LayerGaugeParameters g;g.physical_trace_lapse=false;g.preferred_source=true;g.scri_lapse_damping=2;const auto q=qnf::Gauge(p,u,g,{.85,.95,double(sigma),true});if(!f.valid||!q.valid)throw std::runtime_error("actual parts invalid");return {f.regular,f.pole,q.regular,q.pole};}
D Null(const Point&p,const Jet&u){const auto om=Omega(p,u);const auto g=hyp::Geometry(u.metric);D N=-om.normal*om.normal;for(int i=0;i<3;++i)for(int j=0;j<3;++j)N+=u.chi.value*g.inverse[i][j]*p.domega[i]*p.domega[j];return N;}
std::array<D,2> NullQTime(const Point&p,const Jet&u,const hyp::Z4cRHS<D>&f,const hyp::GaugeRHS<D>&gauge){const auto o=Omega(p,u);const auto geo=hyp::Geometry(u.metric);D Gt{},wt=-o.normal*gauge.alpha;for(int i=0;i<3;++i){wt-=p.domega[i]*gauge.beta[i];for(int j=0;j<3;++j){Gt+=f.chi*geo.inverse[i][j]*p.domega[i]*p.domega[j];for(int k=0;k<3;++k)for(int l=0;l<3;++l)Gt-=u.chi.value*geo.inverse[i][k]*f.metric[k][l]*geo.inverse[l][j]*p.domega[i]*p.domega[j];}}wt/=u.alpha.value;return {Gt-D(2)*o.normal*wt,f.trace-D(3)*wt};}
std::array<Poly,3> BoundaryChart(long double a){const Poly O=Poly::Variable(0),y=Poly::Variable(1),z=Poly::Variable(2);const auto r=Sqrt(Poly(1)-2*a*O),nx=Sqrt(Poly(1)-y*y-z*z);return {r*nx-Poly(1),r*y,r*z};}
// Independent intrinsic scalar curvature of the induced Penrose two-metric.
long double Curvature(const Jet&u,const Frame&e,const std::array<Poly,3>&chart){const auto b=hyp::PenroseMetric(u.metric,u.chi);const D y(Poly::Variable(1)),z(Poly::Variable(2));const D nx=Kokkos::sqrt(D(1)-y*y-z*z);D t[2][3]{};for(int i=0;i<3;++i){t[0][i]=D(e[1][i])-y*D(e[0][i])/nx;t[1][i]=D(e[2][i])-z*D(e[0][i])/nx;}D q[2][2]{};for(int A=0;A<2;++A)for(int B=0;B<2;++B)for(int i=0;i<3;++i)for(int j=0;j<3;++j)q[A][B]+=t[A][i]*t[B][j]*Compose(b.g[i][j],chart);D det=q[0][0]*q[1][1]-q[0][1]*q[1][0];D inv[2][2]={{q[1][1]/det,-q[0][1]/det},{-q[1][0]/det,q[0][0]/det}};D G[2][2][2]{};for(int k=0;k<2;++k)for(int i=0;i<2;++i)for(int j=0;j<2;++j)for(int l=0;l<2;++l)G[k][i][j]+=D(.5)*inv[k][l]*(Derivative(q[l][j],i+1)+Derivative(q[l][i],j+1)-Derivative(q[i][j],l+1));D R{};for(int i=0;i<2;++i)for(int j=0;j<2;++j){D ricci{};for(int k=0;k<2;++k){ricci+=Derivative(G[k][i][j],k+1)-Derivative(G[k][i][k],j+1);for(int l=0;l<2;++l)ricci+=G[k][i][j]*G[l][k][l]-G[l][i][k]*G[k][j][l];}R+=inv[i][j]*ricci;}return R.d.c[0];}
std::vector<std::string> Labels(){std::vector<std::string>labels;auto add=[&](const std::string&name,int maxdegree,int normal){const auto&e=Poly::Exponents();for(int k=0;k<20;++k){int degree=e[k][0]+e[k][1]+e[k][2];if(degree<=maxdegree&&(normal<0||e[k][0]==normal))labels.push_back(name+"["+std::to_string(e[k][0])+","+std::to_string(e[k][1])+","+std::to_string(e[k][2])+"]");}};
 add("H",3,-1);for(int i=0;i<3;++i)add("M"+std::to_string(i),2,-1);for(int i=0;i<3;++i)add("Z"+std::to_string(i),2,-1);add("Theta",3,-1);add("N",3,0);add("N",3,1);add("Qnum",3,0);for(int i=0;i<20;++i)add("R0_"+std::to_string(i),2,0);return labels;}
std::vector<long double> Conditions(const Point&p,const Jet&u,const Frame&e,const std::array<Poly,3>&chart,const V&S){const auto c=hyp::EvolvedConstraints(u,Omega(p,u));if(!c.valid)throw std::runtime_error("constraints invalid");std::vector<long double>out;auto add=[&](const D&x,int maxdegree,int normal){const auto f=Compose(x.d,chart);const auto&ex=Poly::Exponents();for(int k=0;k<20;++k){int degree=ex[k][0]+ex[k][1]+ex[k][2];if(degree<=maxdegree&&(normal<0||ex[k][0]==normal))out.push_back(f.c[k]);}};
 add(c.hamiltonian,3,-1);for(int k=0;k<3;++k){D v;for(int i=0;i<3;++i)v+=D(e[k][i])*c.momentum[i];add(v,2,-1);}for(int k=0;k<3;++k){D v;for(int i=0;i<3;++i)v+=D(e[k][i])*c.z4.z_covector[i];add(v,2,-1);}add(u.theta.value,3,-1);add(Null(p,u),3,0);add(Null(p,u),3,1);add(u.trace.value-D(3)*Omega(p,u).normal,3,0);for(auto s:S)add(s,2,0);return out;}
V NextResidue(const Point&p,const Frame&e,const V&R,const V&S,const std::array<Poly,3>&chart,long double a){const int O=Poly::Index(1,0,0),y=Poly::Index(0,1,0),z=Poly::Index(0,0,1);auto point=Reference({D(e[0][0]),D(e[0][1]),D(e[0][2])},a);auto u=point.state;for(int field=0;field<20;++field){const auto r=Compose(R[field].d,chart),s=Compose(S[field].d,chart);J f;f.v=D(Poly(0),Poly(r.c[0]+s.c[O]));const long double fO=r.c[O]+s.c[Poly::Index(2,0,0)],fy=r.c[y]+s.c[Poly::Index(1,1,0)],fz=r.c[z]+s.c[Poly::Index(1,0,1)];for(int i=0;i<3;++i)f.d[i]=D(Poly(0),Poly(-e[0][i]*fO/a+e[1][i]*fy+e[2][i]*fz));Seed(u,field,f,e);}const auto f=Parts(point,u);return Fields(f.s,f.gs,e);}
void Print(const std::vector<long double>&v){std::cout<<'[';for(std::size_t i=0;i<v.size();++i)std::cout<<(i?",":"")<<v[i];std::cout<<']';}
int main(){try{std::cout<<std::setprecision(21);const long double a=.5L;const auto labels=Labels();std::cout<<"{\"a\":"<<a<<",\"sigma\":3,\"kappa_input\":10,\"eta_outer\":1,\"labels\":[";for(std::size_t i=0;i<labels.size();++i)std::cout<<(i?",":"")<<'"'<<labels[i]<<'"';std::cout<<"],\"orientations\":[";for(int orientation=0;orientation<2;++orientation){const auto e=Axes(orientation);const auto x=Positions(e);const auto p=Reference(x,a);const auto chart=BoundaryChart(a);if(orientation)std::cout<<',';std::cout<<"{\"orientation\":"<<orientation<<",\"columns\":[";for(int monomial=0;monomial<20;++monomial)for(int field=0;field<20;++field){if(monomial||field)std::cout<<',';auto u=p.state;Poly mon;mon.c[monomial]=1;Seed(u,field,SeedJet(mon,e),e);const auto f=Parts(p,u);const auto R=Fields(f.r,f.gr,e),S=Fields(f.s,f.gs,e);const auto evec=Conditions(p,u,e,chart,S);const auto nr=NullQTime(p,u,f.r,f.gr),ns=NullQTime(p,u,f.s,f.gs);const auto Rn=Compose(nr[0].d,chart),Sn=Compose(ns[0].d,chart),Rq=Compose(nr[1].d,chart),Sq=Compose(ns[1].d,chart);const auto next=NextResidue(p,e,R,S,chart,a);const long double N1=Rn.c[Poly::Index(1,0,0)]+Sn.c[Poly::Index(2,0,0)],N0=Rn.c[0]+Sn.c[Poly::Index(1,0,0)],Q0=Rq.c[0]+Sq.c[Poly::Index(1,0,0)];std::cout<<"{\"monomial\":"<<monomial<<",\"field\":"<<field<<",\"E\":";Print(evec);std::cout<<",\"N1_t\":"<<N1<<",\"N0_t\":"<<N0<<",\"Q0_t\":"<<Q0<<",\"delta_Rq\":"<<Curvature(u,e,chart)<<",\"next_R0\":[";for(int i=0;i<20;++i)std::cout<<(i?",":"")<<next[i].d.c[0];std::cout<<"]}";}std::cout<<"]}";}std::cout<<"]}\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
